def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        if len(set(grid[i])) == 1:
            out[i] = [2] * w
    for j in range(w):
        if len(set(grid[i][j] for i in range(h))) == 1:
            for i in range(h):
                out[i][j] = 2
    return out
